(()=>{'use strict';
const KEY='history-voyage-progress-v1';let stats={};try{stats=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{};
const $=s=>document.querySelector(s);const state={mode:'choice',session:[],index:0,correct:0,streak:0,answered:false,current:null};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function record(){try{localStorage.setItem(KEY,JSON.stringify(stats))}catch{} updateSummary()}
function updateSummary(){let values=Object.values(stats),attempts=values.reduce((n,v)=>n+(v.attempts||0),0),hits=values.reduce((n,v)=>n+(v.correct||0),0);$('#total').textContent=QUESTIONS.length;$('#mastered').textContent=values.filter(v=>v.streak>=3).length;$('#accuracy').textContent=attempts?Math.round(hits/attempts*100)+'%':'—'}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function weight(q){let s=stats[q.id];if(!s)return 5;let rate=s.correct/Math.max(1,s.attempts);return Math.max(.18,1.8+(1-rate)*5-(s.streak||0)*.75)+(s.lastWrong?1.8:0)}
function sample(pool,n){let candidates=[...pool],out=[];while(out.length<n&&candidates.length){let w=candidates.map(weight),sum=w.reduce((a,b)=>a+b,0),r=Math.random()*sum,i=0;while(i<w.length-1&&(r-=w[i])>0)i++;out.push(candidates.splice(i,1)[0])}return out}
function chooseSession(){let pool=QUESTIONS.filter(q=>$('#unit').value==='all'||q.unit===$('#unit').value);if($('#weak').checked){let weak=pool.filter(q=>stats[q.id]&&stats[q.id].attempts>stats[q.id].correct);if(weak.length)pool=[...weak,...pool.filter(q=>!weak.includes(q)).slice(0,Math.max(0,10-weak.length))]}return sample(pool,Math.min(10,pool.length))}
function start(){window.VoyageGame.stop();state.session=chooseSession();state.index=0;state.correct=0;state.streak=0;state.answered=false;if(state.mode==='play')startGame();else show()}
function startGame(){let q=state.session;$('#stage').textContent='PLATFORM / 横アクション';$('#counter').textContent=`GATE 0 / ${q.length}`;$('#progress').style.width='0%';window.VoyageGame.start({questions:q,escape,normalize,onGrade:(question,ok)=>{state.correct+=ok?1:0;state.streak=ok?state.streak+1:0;let s=stats[question.id]||{attempts:0,correct:0,streak:0,lastWrong:false};s.attempts++;s.correct+=ok?1:0;s.streak=ok?(s.streak||0)+1:0;s.lastWrong=!ok;stats[question.id]=s;record()},onFinish:({stars})=>{state.index=q.length;finish();$('.done p').insertAdjacentHTML('beforeend',`<br>集めた星：${stars} ✦`)}})}
function normalize(s){return String(s).normalize('NFKC').trim().replace(/[\s　・･、。()（）「」『』]/g,'').replace(/ヶ/g,'ケ').replace(/年$/,'年')}
function answer(value){if(state.answered)return;let q=state.current,ok=normalize(value)===normalize(q.answer);state.answered=true;state.correct+=ok?1:0;state.streak=ok?state.streak+1:0;let s=stats[q.id]||{attempts:0,correct:0,streak:0,lastWrong:false};s.attempts++;s.correct+=ok?1:0;s.streak=ok?(s.streak||0)+1:0;s.lastWrong=!ok;stats[q.id]=s;record();
let chosen=document.querySelectorAll('.choice');chosen.forEach(b=>{b.disabled=true;if(b.dataset.value===q.answer)b.classList.add('correct');else if(b.dataset.value===value)b.classList.add('wrong')});let form=$('.answer-form');if(form){form.querySelector('input').disabled=true;form.querySelector('button').disabled=true}
let fb=document.createElement('div');fb.className='feedback'+(ok?'':' bad');fb.innerHTML=`<strong>${ok?'正解！':'惜しい！ 正解は「'+escape(q.answer)+'」'}</strong><p>${escape(q.explanation)}</p><button class="primary" id="next">${state.index===state.session.length-1?'結果を見る':'次の問題へ'} <span>→</span></button>`;$('#questionBody').append(fb);$('#next').onclick=next;if(state.mode==='play'){let track=$('.voyage-track');if(track)track.textContent='🚢 '+('●'.repeat(Math.min(state.correct,10)))+('○'.repeat(Math.max(0,10-state.correct)));}}
function show(){if(state.index>=state.session.length){finish();return}let q=state.session[state.index];state.current=q;state.answered=false;$('#stage').textContent=state.mode==='play'?'VOYAGE / 探検中':state.mode==='write'?'WRITE / 記入':'QUIZ / 4択';$('#counter').textContent=`QUESTION ${String(state.index+1).padStart(2,'0')} / ${state.session.length}`;$('#progress').style.width=(state.index/state.session.length*100)+'%';let play=state.mode==='play'?`<div class="voyage">航海ログ · ${state.correct} / ${state.session.length} 島に到着　連続正解 ${state.streak}<div class="voyage-track">🚢 ${'●'.repeat(state.correct)}${'○'.repeat(state.session.length-state.correct)}</div></div>`:'';
let choices=shuffle([q.answer,...q.distractors]);$('#card').innerHTML=`<div class="q-area">${play}<span class="unit-badge">${escape(q.unit)}</span><h2>${escape(q.question)}</h2><div id="questionBody">${state.mode==='write'?`<form class="answer-form"><input type="text" aria-label="答えを入力" autocomplete="off" placeholder="答えを入力"><button class="primary" type="submit">答える →</button></form>`:`<div class="choices">${choices.map((v,i)=>`<button class="choice" data-value="${escape(v)}"><span>${'ABCD'[i]}</span>${escape(v)}</button>`).join('')}</div>`}</div><div class="source">教科書 ${escape(q.source.replace('p','p.'))} · 問題 ${q.id} / ${QUESTIONS.length}</div></div>`;
if(state.mode==='write'){let form=$('.answer-form');form.onsubmit=e=>{e.preventDefault();let v=form.querySelector('input').value;if(!v.trim())return;answer(v)};form.querySelector('input').focus()}else document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>answer(b.dataset.value));}
function next(){state.index++;show()}
function finish(){$('#stage').textContent='SESSION COMPLETE';$('#counter').textContent='FINISH';$('#progress').style.width='100%';let percent=Math.round(state.correct/state.session.length*100);$('#card').innerHTML=`<div class="done"><span class="unit-badge">今日の航海、おつかれさま</span><h2>10問の旅を終えました</h2><div class="score">${state.correct} / ${state.session.length}</div><p>正答率 ${percent}% · 覚えた問題は次回から出にくくなります。<br>苦手な問題も、次の航海でまた挑戦できます。</p><button class="primary" id="again">もう10問解く <span>→</span></button></div>`;$('#again').onclick=start}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{document.querySelectorAll('.mode').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.mode=b.dataset.mode});$('#start').onclick=start;initAds();$('#reset').onclick=()=>{if(confirm('この端末の学習記録をすべて消しますか？')){stats={};record()}};updateSummary();
function initAds(){if(typeof VIDEOS==='undefined'||!VIDEOS.length)return;let el=$('#video-ad'),last=-1;function display(){if(document.hidden)return;let n=Math.floor(Math.random()*VIDEOS.length);if(n===last)n=(n+1)%VIDEOS.length;last=n;let v=VIDEOS[n];el.innerHTML=`<div class="ad-shell"><div class="ad-top"><span>おすすめ動画 · 広告</span><button class="ad-close" aria-label="広告を閉じる" title="閉じる">×</button></div><a href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener noreferrer" aria-label="YouTubeで${escape(v.title)}を見る"><img src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt="${escape(v.title)}のサムネイル" loading="lazy"><span class="ad-title">${escape(v.title)}<small>${escape(v.channel)} · YouTubeで見る ↗</small></span></a></div>`;el.hidden=false;el.querySelector('.ad-close').onclick=()=>el.hidden=true}setTimeout(()=>{display();setInterval(display,180000)},45000)}
})();
